<script lang="ts">
 import {schemas,translationFields,type Field} from '#lib/content-schema.ts';import type {Resource} from '#lib/server/api-contract.ts';
 let {resource,values,translation=false,boxTypes=[],refs={},siteId,offerArticleBox=false,noArticleBox=false,canAddArticleBox=false,articleBoxPages=null,fieldError=undefined}: {offerArticleBox?:boolean;canAddArticleBox?:boolean;noArticleBox?:boolean;articleBoxPages?:number[]|null;fieldError?:{field:string;message:string};resource:Resource;values:Record<string,unknown>;translation?:boolean;refs?:Record<string,{value:number;label:string}[]|null>;siteId?:number;boxTypes?:{type:string;settings:Record<string,string[]>;sections:string[]}[]}=$props();
 let selectedType=$derived(String(values.type??''));
 let pickedSite=$state<number|null>(null);
 let articleOn=$state(true);
 const currentSite=$derived(pickedSite??Number(values.site_id??0));
 let flags=$state<Record<string,boolean>>({});
 let lengths=$state<Record<string,number>>({});
 const fields=$derived(schemas[resource].filter(f=>!translation||translationFields[resource]?.includes(f.name)));
 // Empty text is valid in the API. Only the URL/key requires a non-empty value, with its own validation.
 function requiresValue(f:Field){return !translation&&(f.name==='link'||f.name==='key');}
 function value(f:Field){const v=values[f.name];return f.kind==='json'?JSON.stringify(v??{},null,2):f.kind==='ids'?Array.isArray(v)?v.join(', '):String(v??''):String(v??((f.kind==='number'||f.kind==='boolean')?0:''));}
 function isOn(f:Field){return flags[f.name]??Number(values[f.name])===1;}
 const hints:Record<string,string>={'articles.site_id':'Which page of the site the article appears on. An article cannot be published without a selected page.','pages.parent_id':'Which page this page is placed under. None means a top-level page.','menu.site_id':'Which page the menu item links to.','menu.parent':'Which menu item this item is placed under. None means the top level.','boxes.section_id':'Which section of the page the box appears in.','articles.author':'Optional. The author name shown with the article.','articles.source':'Optional. Write anything: an address, a book title, a name. Only a valid http(s) address is shown as a link on the site. Leave the field empty for private texts.','pages.link':'Page address, for example /about-us/. We add the trailing slash automatically.'};
 const placeholders:Record<string,string>={'pages.link':'/about-us/'};
 const toggleHints:Record<string,string>={visible:'On: the page or item is visible on the site.',strict:'On: the address must match exactly.',acl:'On: shown only to users with permission.',active:'On: the section is used on the site.',static:'On: the box content does not change by page.',shared:'On: the box can be shared across several pages.',device_strict:'On: the box is shown only on the chosen device.'};
 function options(f:Field){const list=refs[f.name];if(!Array.isArray(list))return null;const current=Number(values[f.name]);return current>0&&!list.some(o=>o.value===current)?[...list,{value:current,label:'ID '+current+' (record not found in the list)'}]:list;}
 const zeroLabels:Record<string,string>={'articles.site_id':'Not selected yet (the article cannot be published)','pages.parent_id':'None (root)','menu.site_id':'Not selected yet','menu.parent':'None (root)','boxes.section_id':'Not selected yet'};
 const nf=new Intl.NumberFormat('en-GB');
 function count(f:Field){return lengths[f.name]??value(f).length;}
 function wide(f:Field){return f.kind==='textarea'||f.kind==='json'||f.kind==='format'||(f.kind===undefined&&(f.max??0)>=100);}

 $effect(()=>{if(!fieldError)return;const el=document.querySelector<HTMLElement>('[name="'+fieldError.field+'"]');if(el){el.setAttribute('aria-invalid','true');el.scrollIntoView({block:'center',behavior:'smooth'});el.focus({preventScroll:true})}});
</script>
<div class="grid gap-5 sm:grid-cols-2">
{#each fields as spec}
 {#if resource==='boxes'&&spec.name==='type'}<label class="field sm:col-span-2"><span>{spec.label}</span><select name="type" bind:value={selectedType} required><option value="">Select a registered type</option>{#each boxTypes as type}<option value={type.type}>{type.type} (sections: {type.sections.join(', ')})</option>{/each}</select>
</label>
 {:else if resource==='boxes'&&spec.name==='settings'}{#each Object.entries(boxTypes.find(x=>x.type===selectedType)?.settings??{}) as [name,options]}<label class="field"><span>{name}</span><select name={'setting_'+name}>
<option value="">Default value</option>{#each options as option}<option value={option} selected={(values.settings as Record<string,unknown>|undefined)?.[name]===option}>{option}</option>{/each}</select>
</label>{/each}
 {:else if spec.kind==='textarea'}<label class="field sm:col-span-2"><span>{spec.label}</span><textarea autocomplete="off" class="resize-y font-mono text-[.9rem] leading-relaxed {spec.name==='bodytext'?'min-h-96':'min-h-36'}" name={spec.name} rows={spec.name==='bodytext'?16:5} maxlength={spec.max} spellcheck="true" oninput={(e)=>{lengths[spec.name]=e.currentTarget.value.length;}}>{value(spec)}</textarea>
<span class="hint flex justify-between gap-3"><span>Markdown: **bold**, *italic*, [link](https://), ![image](/path)</span><span aria-live="polite">{nf.format(count(spec))}{#if spec.max} / {nf.format(spec.max)}{/if} characters</span></span>
</label>
 {:else if spec.kind==='boolean'}<div class="toggle-row flex items-center justify-between gap-4 rounded-xl border border-line bg-surface-2 px-4 py-3"><label class="flex w-full cursor-pointer items-center justify-between gap-4"><span class="grid gap-0.5"><span class="font-semibold">{spec.label}</span><span class="hint">{toggleHints[spec.name]??''}</span></span><span class="flex shrink-0 items-center gap-3"><span class="w-16 text-right text-sm font-semibold {isOn(spec)?'text-ok':'text-muted'}" aria-hidden="true">{isOn(spec)?'On':'Off'}</span><input type="checkbox" role="switch" class="peer sr-only" name={spec.name} value="1" checked={isOn(spec)} onchange={(e)=>{flags[spec.name]=e.currentTarget.checked;}}/><span class="relative h-6 w-11 rounded-full border border-line-strong bg-line-strong transition-colors peer-checked:border-brand peer-checked:bg-brand peer-focus-visible:ring-2 peer-focus-visible:ring-brand peer-focus-visible:ring-offset-2 peer-focus-visible:ring-offset-surface after:absolute after:left-0.5 after:top-0.5 after:h-5 after:w-5 after:rounded-full after:bg-surface after:shadow after:transition-transform after:content-[''] peer-checked:after:translate-x-5" aria-hidden="true"></span></span></label></div>
 {:else if refs[spec.name]!==undefined}{@const list=options(spec)}{#if list&&list.length===0}<div class="field sm:col-span-2"><span>{spec.label}</span><input type="hidden" name={spec.name} value={String(values[spec.name]??0)}/><p class="alert alert-warn" role="status">The site has no page yet. {#if siteId}<a href={'/content/'+siteId+'/pages/new'}>Create the first page</a>{:else}Create a page first{/if} and then come back here.</p></div>
 {:else if list}<label class="field"><span>{spec.label}</span><select name={spec.name} onchange={resource==='articles'&&spec.name==='site_id'?(e)=>{pickedSite=Number(e.currentTarget.value);}:undefined}><option value="0" selected={Number(values[spec.name]??0)===0}>{zeroLabels[resource+'.'+spec.name]??'Not selected'}</option>{#each list as option}<option value={option.value} selected={Number(values[spec.name])===option.value}>{option.label}</option>{/each}</select><span class="hint">{hints[resource+'.'+spec.name]??''}</span>{#if resource==='articles'&&spec.name==='site_id'&&Array.isArray(articleBoxPages)&&currentSite>0&&!articleBoxPages.includes(currentSite)}<span class="hint rounded-lg border border-line bg-surface-2 px-3 py-2" role="status">This page does not have a box that displays articles yet, so the article will not appear on the site. {#if canAddArticleBox}<label class="mt-1 flex items-center gap-2 font-semibold text-text"><input type="checkbox" name="add_article_box" value="1" checked/> On save, add an article box to this page</label>{:else if siteId}<a href={'/content/'+siteId+'/boxes/new'}>Add box</a>{/if}</span>{/if}</label>
 {:else}<label class="field"><span>{spec.label} (numeric ID)</span><input type="number" min="0" step="1" name={spec.name} value={value(spec)}/><span class="hint">{hints[resource+'.'+spec.name]??''} The list could not be loaded, enter the numeric record ID (0 means not selected).</span></label>{/if}
 {:else if spec.kind==='format'}<label class="field sm:col-span-2"><span>{spec.label}</span><select name={spec.name}>
<option value="markdown" selected={values.content_format!=='legacy_html'}>Markdown</option>{#if values.content_format==='legacy_html'}<option value="legacy_html" selected>Existing HTML, metadata changes only</option>{/if}</select>
<span class="hint">To change the original HTML, explicitly select Markdown and replace both the intro and the full text.</span>
</label>
 {:else if spec.kind==='json'}<label class="field sm:col-span-2"><span>{spec.label}</span><input class="font-mono text-[.9rem]" type="text" name={spec.name} value={value(spec)} maxlength={spec.max}/></label>
 {:else}<label class="field {wide(spec)?'sm:col-span-2':''}"><span>{spec.label}</span><input type={spec.kind==='number'?'number':'text'} min={spec.kind==='number'?0:undefined} step={spec.kind==='number'?1:undefined} name={spec.name} value={value(spec)} maxlength={spec.max} required={requiresValue(spec)} placeholder={placeholders[resource+'.'+spec.name]} autocomplete="off" aria-invalid={fieldError?.field===spec.name?'true':undefined}/>
{#if hints[resource+'.'+spec.name]}<span class="hint">{hints[resource+'.'+spec.name]}</span>{/if}
</label>{/if}
{/each}
{#if offerArticleBox}<div class="toggle-row flex items-center justify-between gap-4 rounded-xl border border-line bg-surface-2 px-4 py-3 sm:col-span-2"><label class="flex w-full cursor-pointer items-center justify-between gap-4"><span class="grid gap-0.5"><span class="font-semibold">Show an article on this page</span><span class="hint">On: we automatically add a box to the new page that displays a published article. Without it the page would stay empty.</span></span><span class="flex shrink-0 items-center gap-3"><span class="w-16 text-right text-sm font-semibold {articleOn?'text-ok':'text-muted'}" aria-hidden="true">{articleOn?'On':'Off'}</span><input type="checkbox" role="switch" class="peer sr-only" name="show_article" value="1" checked={articleOn} onchange={(e)=>{articleOn=e.currentTarget.checked;}}/><span class="relative h-6 w-11 rounded-full border border-line-strong bg-line-strong transition-colors peer-checked:border-brand peer-checked:bg-brand peer-focus-visible:ring-2 peer-focus-visible:ring-brand peer-focus-visible:ring-offset-2 peer-focus-visible:ring-offset-surface after:absolute after:left-0.5 after:top-0.5 after:h-5 after:w-5 after:rounded-full after:bg-surface after:shadow after:transition-transform after:content-[''] peer-checked:after:translate-x-5" aria-hidden="true"></span></span></label></div>
{:else if noArticleBox}<p class="alert alert-info sm:col-span-2" role="status">This site cannot yet add an article box to a new page by itself, so the page will not display any article on its own. After creating the page, add a box of type story in the Boxes section (if the site offers it) and assign this page to it, or contact the site administrator.</p>{/if}
</div>
